reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","user_metadata":{"role":"ADMIN"}}',true);
select is((select count(*)::integer from public.student_profiles),1,'user-controlled metadata does not grant admin access');
reset role;
-- Authorization follows relationship removal immediately.
delete from public.consents where parent_id='10000000-0000-0000-0000-000000000001';
delete from public.parent_student_relationships where parent_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.student_profiles),0,'revoked parent cannot read student');
